export default ForgotPasswordPage;

import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { useNavigate, Link } from 'react-router-dom';
import { LogIn, User, Lock, Loader2, AlertCircle, ArrowRight, Mail, RefreshCw } from 'lucide-react';
import Logo from '../components/Logo';
import api from '../services/api';

const LoginPage = () => {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [emailNotVerified, setEmailNotVerified] = useState(null); // stores email for resend
    const [resendLoading, setResendLoading] = useState(false);
    const [resendSuccess, setResendSuccess] = useState(false);
    const { login } = useAuth();
    const navigate = useNavigate();

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError('');
        setEmailNotVerified(null);
        setResendSuccess(false);
        try {
            await login(email, password);
            navigate('/');
        } catch (err) {
            const data = err.response?.data;

            // Handle email not verified
            if (data?.code === 'EMAIL_NOT_VERIFIED') {
                setEmailNotVerified(data.email);
                setError(data.message);
            } else {
                setError(data?.message || 'Échec de la connexion. Veuillez vérifier vos identifiants.');
            }
        } finally {
            setLoading(false);
        }
    };

    const handleResendVerification = async () => {
        if (!emailNotVerified) return;
        setResendLoading(true);
        try {
            await api.post('/auth/resend-verification', { email: emailNotVerified });
            setResendSuccess(true);
        } catch {
            // Silently handle
        } finally {
            setResendLoading(false);
        }
    };

    return (
        <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex items-center justify-center p-4 transition-colors duration-300">
            <div className="max-w-md w-full card !p-8 animate-in fade-in zoom-in duration-300">
                <div className="text-center mb-8">
                    <div className="flex justify-center mb-6">
                        <Logo className="scale-125" textColor="text-slate-800 dark:text-slate-100" />
                    </div>
                    <h1 className="text-3xl font-bold text-slate-800 dark:text-white tracking-tight">Bienvenue</h1>
                    <p className="text-slate-500 dark:text-slate-400 mt-2 font-medium">Connectez-vous à votre espace EniGov</p>
                </div>

                {error && (
                    <div className="bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 p-4 rounded-xl text-sm mb-6 border border-red-100 dark:border-red-900/30">
                        <div className="flex items-start gap-3">
                            <AlertCircle className="shrink-0 mt-0.5" size={18} />
                            <span>{error}</span>
                        </div>

                        {/* Resend verification button */}
                        {emailNotVerified && (
                            <div className="mt-3 pt-3 border-t border-red-100 dark:border-red-900/30">
                                {resendSuccess ? (
                                    <p className="text-green-600 dark:text-green-400 text-sm font-medium flex items-center gap-2">
                                        <Mail size={16} /> Email de vérification renvoyé !
                                    </p>
                                ) : (
                                    <button
                                        onClick={handleResendVerification}
                                        disabled={resendLoading}
                                        className="text-primary-600 dark:text-primary-400 font-bold text-sm hover:underline underline-offset-4 flex items-center gap-2"
                                    >
                                        {resendLoading ? (
                                            <Loader2 className="animate-spin" size={14} />
                                        ) : (
                                            <RefreshCw size={14} />
                                        )}
                                        Renvoyer l'email de vérification
                                    </button>
                                )}
                            </div>
                        )}
                    </div>
                )}

                <form onSubmit={handleSubmit} className="space-y-5">
                    <div className="space-y-2">
                        <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1">Email</label>
                        <div className="relative group">
                            <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary-500 transition-colors" size={20} />
                            <input
                                type="email"
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                className="input !pl-12 !py-3.5"
                                placeholder="prenom.nom@enicar.ucar.tn"
                                required
                            />
                        </div>
                    </div>

                    <div className="space-y-2">
                        <div className="flex items-center justify-between">
                            <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1">Mot de passe</label>
                            <Link
                                to="/forgot-password"
                                className="text-xs text-primary-600 dark:text-primary-400 font-semibold hover:underline underline-offset-4"
                            >
                                Oublié ?
                            </Link>
                        </div>
                        <div className="relative group">
                            <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary-500 transition-colors" size={20} />
                            <input
                                type="password"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="input !pl-12 !py-3.5"
                                placeholder="••••••••"
                                required
                            />
                        </div>
                    </div>

                    <button
                        type="submit"
                        disabled={loading}
                        className="btn-primary w-full !py-4 flex items-center justify-center gap-3 mt-8 shadow-lg shadow-primary-200 dark:shadow-none"
                    >
                        {loading ? (
                            <Loader2 className="animate-spin" size={22} />
                        ) : (
                            <>
                                <span className="text-lg">Se connecter</span>
                                <ArrowRight size={20} />
                            </>
                        )}
                    </button>
                </form>

                <div className="mt-8 pt-8 border-t border-slate-50 dark:border-slate-800 text-center">
                    <p className="text-slate-500 dark:text-slate-400 text-sm font-medium">
                        Pas encore de compte ?{' '}
                        <Link to="/register" className="text-primary-600 dark:text-primary-400 font-bold hover:underline underline-offset-4">
                            S'inscrire
                        </Link>
                    </p>
                </div>
            </div>
        </div>
    );
};

export default LoginPage;

import React, { useState, useEffect, useRef } from 'react';
import DashboardLayout from '../components/DashboardLayout';
import api from '../services/api';
import { useAuth } from '../context/AuthContext';
import {
    Send,
    Search,
    Check,
    CheckCheck,
    Loader2,
    MessageSquare,
    Plus
} from 'lucide-react';

const MessagingPage = () => {
    const { user } = useAuth();
    const isDelegue = user?.role === 'ROLE_DELEGUE';

    const [conversations, setConversations] = useState([]);
    const [contacts, setContacts] = useState([]);
    const [messages, setMessages] = useState([]);
    const [activeContact, setActiveContact] = useState(null);
    const [message, setMessage] = useState('');
    const [loading, setLoading] = useState(true);
    const [sending, setSending] = useState(false);
    const [isStartingNew, setIsStartingNew] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const messagesEndRef = useRef(null);

    useEffect(() => {
        fetchConversations();
        fetchContacts();
    }, []);

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages]);

    const fetchConversations = async () => {
        try {
            const res = await api.get('/messages/conversations');
            setConversations(res.data);
            // Auto-select first conversation if none active
            if (!activeContact && res.data.length > 0) {
                const first = res.data[0];
                setActiveContact({ id: first.otherUserId, name: first.otherUserName, profilePhoto: first.profilePhoto });
                fetchHistory(first.otherUserId);
            }
        } catch {
            setConversations([]);
        } finally {
            setLoading(false);
        }
    };

    const fetchContacts = async () => {
        try {
            const res = await api.get('/messages/contacts');
            setContacts(res.data);
        } catch {
            setContacts([]);
        }
    };

    const fetchHistory = async (userId) => {
        try {
            const res = await api.get(`/messages/history/${userId}`);
            setMessages(res.data);
        } catch {
            setMessages([]);
        }
    };

    const handleSelectContact = (contact) => {
        const id = contact.otherUserId || contact.id;
        const name = contact.otherUserName || contact.fullName || contact.name;
        const profilePhoto = contact.profilePhoto;
        setActiveContact({ id, name, profilePhoto });
        fetchHistory(id);
        setIsStartingNew(false);
        setSearchQuery('');
    };

    const handleSend = async (e) => {
        e.preventDefault();
        if (!message.trim() || !activeContact || sending) return;
        setSending(true);
        try {
            await api.post('/messages', {
                content: message,
                recipientId: activeContact.id
            });
            setMessage('');
            await fetchHistory(activeContact.id);
            fetchConversations();
        } catch (err) {
            alert(err.response?.data?.message || "Erreur lors de l'envoi");
        } finally {
            setSending(false);
        }
    };

    const isActive = (contactId) => activeContact?.id === contactId;

    const renderAvatar = (name, profilePhoto, size = 'w-10 h-10', rounded = 'rounded-xl', colorClass = 'bg-primary-100 dark:bg-primary-900/30 text-primary-600 dark:text-primary-400') => {
        if (profilePhoto) {
            const src = profilePhoto.startsWith('http') 
                ? profilePhoto 
                : `${import.meta.env.VITE_API_URL?.replace('/api', '') || 'http://localhost:8081'}/uploads/${profilePhoto}`;
            return (
                <div className={`${size} ${rounded} overflow-hidden shrink-0`}>
                    <img src={src} alt={name} className="w-full h-full object-cover" />
                </div>
            );
        }
        return (
            <div className={`${size} ${colorClass} ${rounded} flex items-center justify-center font-bold uppercase shrink-0`}>
                {(name || '?').charAt(0)}
            </div>
        );
    };

    return (
        <DashboardLayout title="Messagerie">
            <div className="h-[calc(100vh-160px)] flex gap-4 overflow-hidden">
                {/* Sidebar — Conversations */}
                <div className="w-80 card !p-0 flex flex-col overflow-hidden shrink-0">
                    <div className="p-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">
                        <h3 className="font-bold text-slate-800 dark:text-white">Messages</h3>
                        <button
                            onClick={() => setIsStartingNew(!isStartingNew)}
                            className={`p-2 rounded-lg transition-all ${isStartingNew ? 'bg-primary-600 text-white' : 'text-primary-600 hover:bg-primary-50 dark:hover:bg-primary-900/20'}`}
                            title="Nouveau message"
                        >
                            <Plus size={18} />
                        </button>
                    </div>

                    {/* Search */}
                    <div className="px-4 py-3 border-b border-slate-100 dark:border-slate-800">
                        <div className="relative">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                            <input
                                type="text"
                                placeholder="Rechercher..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                className="w-full bg-slate-50 dark:bg-slate-800 text-xs py-2 pl-8 pr-3 rounded-lg border-none outline-none dark:text-slate-200"
                            />
                        </div>
                    </div>

                    {/* Contact list */}
                    <div className="flex-1 overflow-y-auto">
                        {loading ? (
                            <div className="py-12 flex justify-center">
                                <Loader2 size={20} className="animate-spin text-slate-400" />
                            </div>
                        ) : isStartingNew ? (
                            <div className="p-2">
                                <p className="px-3 py-2 text-[10px] font-bold text-slate-400 uppercase tracking-widest">Contacts disponibles</p>
                                {contacts
                                    .filter(c => (c.fullName || '').toLowerCase().includes(searchQuery.toLowerCase()))
                                    .map((c) => (
                                        <div
                                            key={c.id}
                                            onClick={() => handleSelectContact(c)}
                                            className="p-3 mx-1 flex items-center gap-3 cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-800/50 rounded-lg transition-all"
                                        >
                                            {renderAvatar(c.fullName, c.profilePhoto, 'w-9 h-9', 'rounded-lg', 'bg-primary-100 dark:bg-primary-900/30 text-primary-600 dark:text-primary-400 text-xs')}
                                            <div>
                                                <p className="font-semibold text-sm text-slate-800 dark:text-white">{c.fullName}</p>
                                                <p className="text-[10px] text-slate-400">{(c.role || '').replace('ROLE_', '')}</p>
                                            </div>
                                        </div>
                                    ))}
                                {contacts.filter(c => (c.fullName || '').toLowerCase().includes(searchQuery.toLowerCase())).length === 0 && (
                                    <p className="p-6 text-center text-xs text-slate-400">Aucun contact trouvé.</p>
                                )}
                            </div>
                        ) : conversations.length > 0 ? (
                            conversations
                                .filter(c => (c.otherUserName || '').toLowerCase().includes(searchQuery.toLowerCase()))
                                .map((c) => (
                                    <div
                                        key={c.otherUserId}
                                        onClick={() => handleSelectContact(c)}
                                        className={`p-4 flex items-center gap-3 cursor-pointer transition-colors border-l-3 ${
                                            isActive(c.otherUserId)
                                                ? 'bg-primary-50/50 dark:bg-primary-900/10 border-l-4 border-primary-600'
                                                : 'border-l-4 border-transparent hover:bg-slate-50 dark:hover:bg-slate-800/50'
                                        }`}
                                    >
                                        {renderAvatar(c.otherUserName, c.profilePhoto, 'w-10 h-10', 'rounded-xl', 'bg-primary-100 dark:bg-primary-900/30 text-primary-600 dark:text-primary-400')}
                                        <div className="flex-1 min-w-0">
                                            <div className="flex items-center justify-between mb-0.5">
                                                <span className="font-semibold text-sm text-slate-800 dark:text-white truncate">{c.otherUserName}</span>
                                                <span className="text-[10px] text-slate-400 shrink-0">
                                                    {c.lastTimestamp ? new Date(c.lastTimestamp).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' }) : ''}
                                                </span>
                                            </div>
                                            <div className="flex items-center justify-between">
                                                <p className="text-xs text-slate-500 truncate pr-2">{c.lastMessage}</p>
                                                {c.unreadCount > 0 && (
                                                    <span className="w-5 h-5 bg-primary-600 text-white text-[9px] font-bold rounded-full flex items-center justify-center shrink-0">
                                                        {c.unreadCount}
                                                    </span>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                ))
                        ) : (
                            <div className="p-8 text-center">
                                <MessageSquare size={32} className="mx-auto mb-3 text-slate-300 dark:text-slate-600" />
                                <p className="text-sm text-slate-400 mb-2">Aucune conversation.</p>
                                <button
                                    onClick={() => setIsStartingNew(true)}
                                    className="text-xs font-semibold text-primary-600 hover:underline"
                                >
                                    Démarrer une discussion
                                </button>
                            </div>
                        )}
                    </div>
                </div>

                {/* Chat Window */}
                <div className="flex-1 card !p-0 flex flex-col overflow-hidden">
                    {!activeContact ? (
                        <div className="flex-1 flex flex-col items-center justify-center text-slate-400 p-8 text-center">
                            <MessageSquare size={48} className="mb-4 opacity-20" />
                            <h3 className="text-lg font-bold text-slate-700 dark:text-slate-300 mb-1">Messagerie</h3>
                            <p className="text-sm max-w-xs">
                                {isDelegue
                                    ? 'Sélectionnez une conversation ou contactez un étudiant.'
                                    : 'Envoyez un message au délégué.'
                                }
                            </p>
                        </div>
                    ) : (
                        <>
                            {/* Chat header */}
                            <div className="px-6 py-4 border-b border-slate-100 dark:border-slate-800 flex items-center gap-3 bg-white/50 dark:bg-slate-900/50 backdrop-blur-sm">
                                {renderAvatar(activeContact.name, activeContact.profilePhoto, 'w-10 h-10', 'rounded-xl', 'bg-primary-600 text-white')}
                                <div>
                                    <h4 className="font-bold text-slate-800 dark:text-white text-sm">{activeContact.name}</h4>
                                    <span className="text-[10px] text-slate-400">Conversation privée</span>
                                </div>
                            </div>

                            {/* Messages */}
                            <div className="flex-1 p-6 overflow-y-auto space-y-4 bg-slate-50/30 dark:bg-slate-950/20">
                                {messages.length === 0 && (
                                    <p className="text-center text-xs text-slate-400 py-8">Aucun message. Commencez la discussion !</p>
                                )}
                                {messages.map((m) => {
                                    const isMine = m.senderId === user?.id;
                                    return (
                                        <div key={m.id} className={`flex ${isMine ? 'justify-end' : 'justify-start'}`}>
                                            <div className={`max-w-[70%] p-3 rounded-2xl ${
                                                isMine
                                                    ? 'bg-primary-600 text-white rounded-tr-sm'
                                                    : 'bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-300 rounded-tl-sm border border-slate-100 dark:border-slate-700'
                                            }`}>
                                                <p className="text-sm leading-relaxed">{m.content}</p>
                                                <div className={`flex items-center justify-end gap-1 mt-1 ${isMine ? 'text-primary-200' : 'text-slate-400'}`}>
                                                    <span className="text-[9px] font-medium">
                                                        {m.timestamp ? new Date(m.timestamp).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' }) : ''}
                                                    </span>
                                                    {isMine && (m.read ? <CheckCheck size={12} /> : <Check size={12} />)}
                                                </div>
                                            </div>
                                        </div>
                                    );
                                })}
                                <div ref={messagesEndRef} />
                            </div>

                            {/* Input */}
                            <form onSubmit={handleSend} className="p-4 border-t border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900">
                                <div className="flex items-center gap-2 bg-slate-50 dark:bg-slate-800 p-2 rounded-xl">
                                    <input
                                        value={message}
                                        onChange={(e) => setMessage(e.target.value)}
                                        placeholder="Écrivez votre message..."
                                        className="flex-1 bg-transparent border-none outline-none text-sm text-slate-700 dark:text-slate-200 placeholder-slate-400 px-2"
                                    />
                                    <button
                                        type="submit"
                                        disabled={sending || !message.trim()}
                                        className={`p-2.5 rounded-lg transition-all ${
                                            sending || !message.trim()
                                                ? 'bg-slate-200 dark:bg-slate-700 text-slate-400 cursor-not-allowed'
                                                : 'bg-primary-600 text-white hover:bg-primary-700'
                                        }`}
                                    >
                                        <Send size={16} className={sending ? 'animate-pulse' : ''} />
                                    </button>
                                </div>
                            </form>
                        </>
                    )}
                </div>
            </div>
        </DashboardLayout>
    );
};

export default MessagingPage;

import React, { useState, useEffect } from 'react';
import DashboardLayout from '../components/DashboardLayout';
import api from '../services/api';
import { useAuth } from '../context/AuthContext';
import {
    Plus,
    Clock,
    CheckCircle2,
    Lock,
    Trash2,
    Send,
    Loader2,
    BarChart3,
    Users,
    X,
    ChevronDown,
    ChevronUp,
    Globe,
    Target
} from 'lucide-react';

const FILIERES = [
    { value: 'INFO', label: 'Informatique', short: 'INFO' },
    { value: 'INFOTRO', label: 'Infotronique', short: 'INFOTRO' },
    { value: 'MECA', label: 'Mécatronique', short: 'MECA' },
    { value: 'GSIL', label: 'GSIL', short: 'GSIL' }
];

const PROMOTIONS = [
    { value: 'PREMIERE_ANNEE', label: '1ère année', short: '1A' },
    { value: 'DEUXIEME_ANNEE', label: '2ème année', short: '2A' },
    { value: 'TROISIEME_ANNEE', label: '3ème année', short: '3A' }
];

const TargetBadge = ({ targetAll, targetLabel }) => {
    if (targetAll) {
        return (
            <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-lg text-[10px] font-bold bg-blue-50 text-blue-600 dark:bg-blue-900/20 dark:text-blue-400">
                <Globe size={10} /> Tous
            </span>
        );
    }
    return (
        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-lg text-[10px] font-bold bg-amber-50 text-amber-600 dark:bg-amber-900/20 dark:text-amber-400 max-w-[200px] truncate" title={targetLabel}>
            <Target size={10} /> {targetLabel || 'Ciblé'}
        </span>
    );
};

const PollsPage = () => {
    const { user } = useAuth();
    const isDelegue = user?.role === 'ROLE_DELEGUE';

    const [polls, setPolls] = useState([]);
    const [loading, setLoading] = useState(true);
    const [showForm, setShowForm] = useState(false);
    const [question, setQuestion] = useState('');
    const [options, setOptions] = useState(['', '']);
    const [deadline, setDeadline] = useState('');
    const [submitting, setSubmitting] = useState(false);
    const [expandedVoters, setExpandedVoters] = useState({});

    // Target audience state
    const [targetAll, setTargetAll] = useState(true);
    const [selectedFilieres, setSelectedFilieres] = useState([]);
    const [selectedPromotions, setSelectedPromotions] = useState([]);

    useEffect(() => {
        fetchPolls();
    }, []);

    const fetchPolls = async () => {
        setLoading(true);
        try {
            const res = await api.get('/polls');
            setPolls(res.data);
        } catch {
            setPolls([]);
        } finally {
            setLoading(false);
        }
    };

    const toggleFiliere = (value) => {
        setSelectedFilieres(prev =>
            prev.includes(value) ? prev.filter(f => f !== value) : [...prev, value]
        );
    };

    const togglePromotion = (value) => {
        setSelectedPromotions(prev =>
            prev.includes(value) ? prev.filter(p => p !== value) : [...prev, value]
        );
    };

    const resetForm = () => {
        setQuestion('');
        setOptions(['', '']);
        setDeadline('');
        setTargetAll(true);
        setSelectedFilieres([]);
        setSelectedPromotions([]);
    };

    const handleCreate = async (e) => {
        e.preventDefault();
        const filteredOptions = options.filter(o => o.trim());
        if (!question.trim() || filteredOptions.length < 2) return;
        setSubmitting(true);
        try {
            const payload = {
                question,
                options: filteredOptions,
                deadline: deadline || null,
                targetAudience: {
                    targetAll,
                    filieres: targetAll ? [] : selectedFilieres,
                    promotions: targetAll ? [] : selectedPromotions
                }
            };
            await api.post('/polls', payload);
            setShowForm(false);
            resetForm();
            fetchPolls();
        } catch (err) {
            alert(err.response?.data?.message || 'Erreur lors de la création');
        } finally {
            setSubmitting(false);
        }
    };

    const handleVote = async (pollId, optionIndex) => {
        try {
            const res = await api.post(`/polls/${pollId}/vote`, { optionIndex });
            setPolls(prev => prev.map(p => p.id === pollId ? res.data : p));
        } catch (err) {
            alert(err.response?.data?.message || 'Erreur lors du vote');
        }
    };

    const handleClose = async (id) => {
        if (!window.confirm('Clôturer ce sondage ?')) return;
        try {
            await api.put(`/polls/${id}/close`);
            fetchPolls();
        } catch (err) {
            alert(err.response?.data?.message || 'Erreur');
        }
    };

    const handleDelete = async (id) => {
        if (!window.confirm('Supprimer ce sondage ?')) return;
        try {
            await api.delete(`/polls/${id}`);
            fetchPolls();
        } catch (err) {
            alert(err.response?.data?.message || 'Erreur');
        }
    };

    const toggleVoters = (pollId, optIndex) => {
        const key = `${pollId}-${optIndex}`;
        setExpandedVoters(prev => ({ ...prev, [key]: !prev[key] }));
    };

    return (
        <DashboardLayout title="Sondages">
            <div className="max-w-4xl mx-auto space-y-6">
                {/* Header */}
                <div className="flex items-center justify-between">
                    <div>
                        <h1 className="text-xl font-bold text-slate-800 dark:text-white">Sondages</h1>
                        <p className="text-sm text-slate-500">Participez aux décisions de votre université</p>
                    </div>
                    {isDelegue && (
                        <button onClick={() => setShowForm(true)} className="btn-primary flex items-center gap-2 text-sm">
                            <Plus size={16} /> Nouveau Sondage
                        </button>
                    )}
                </div>

                {/* Creation Modal */}
                {showForm && (
                    <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
                        <div className="bg-white dark:bg-slate-900 rounded-2xl shadow-2xl w-full max-w-lg animate-in fade-in zoom-in duration-200 max-h-[90vh] overflow-y-auto">
                            <div className="p-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between sticky top-0 bg-white dark:bg-slate-900 z-10 rounded-t-2xl">
                                <h3 className="text-lg font-bold text-slate-800 dark:text-white">Nouveau Sondage</h3>
                                <button onClick={() => { setShowForm(false); resetForm(); }} className="text-slate-400 hover:text-slate-600">
                                    <X size={20} />
                                </button>
                            </div>
                            <form onSubmit={handleCreate} className="p-5 space-y-4">
                                <div>
                                    <label className="text-sm font-bold text-slate-700 dark:text-slate-300 mb-1 block">Question</label>
                                    <input
                                        className="input"
                                        value={question}
                                        onChange={(e) => setQuestion(e.target.value)}
                                        placeholder="ex: Faut-il décaler les examens ?"
                                        required
                                    />
                                </div>
                                <div>
                                    <label className="text-sm font-bold text-slate-700 dark:text-slate-300 mb-1 block">Options</label>
                                    <div className="space-y-2">
                                        {options.map((opt, idx) => (
                                            <div key={idx} className="flex gap-2">
                                                <input
                                                    className="input flex-1"
                                                    value={opt}
                                                    onChange={(e) => {
                                                        const newOpts = [...options];
                                                        newOpts[idx] = e.target.value;
                                                        setOptions(newOpts);
                                                    }}
                                                    placeholder={`Option ${idx + 1}`}
                                                    required={idx < 2}
                                                />
                                                {idx >= 2 && (
                                                    <button
                                                        type="button"
                                                        onClick={() => setOptions(options.filter((_, i) => i !== idx))}
                                                        className="p-2 text-slate-400 hover:text-red-500"
                                                    >
                                                        <X size={16} />
                                                    </button>
                                                )}
                                            </div>
                                        ))}
                                        <button
                                            type="button"
                                            onClick={() => setOptions([...options, ''])}
                                            className="text-sm font-semibold text-primary-600 hover:underline"
                                        >
                                            + Ajouter une option
                                        </button>
                                    </div>
                                </div>

                                {/* Target Audience Section */}
                                <div className="border border-slate-200 dark:border-slate-700 rounded-xl p-4 space-y-3">
                                    <div className="flex items-center justify-between">
                                        <label className="text-sm font-bold text-slate-700 dark:text-slate-300 flex items-center gap-2">
                                            <Users size={16} className="text-primary-500" /> Public cible
                                        </label>
                                        <button
                                            type="button"
                                            onClick={() => { setTargetAll(!targetAll); if (!targetAll) { setSelectedFilieres([]); setSelectedPromotions([]); } }}
                                            className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${targetAll ? 'bg-primary-500' : 'bg-slate-300 dark:bg-slate-600'}`}
                                        >
                                            <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform shadow-sm ${targetAll ? 'translate-x-6' : 'translate-x-1'}`} />
                                        </button>
                                    </div>

                                    {targetAll ? (
                                        <p className="text-xs text-slate-400 flex items-center gap-1">
                                            <Globe size={12} /> Visible par tous les étudiants
                                        </p>
                                    ) : (
                                        <div className="space-y-3 animate-in fade-in slide-in-from-top-2 duration-200">
                                            <div>
                                                <p className="text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5 uppercase tracking-wider">Filières</p>
                                                <div className="flex flex-wrap gap-1.5">
                                                    {FILIERES.map((f) => (
                                                        <button
                                                            key={f.value}
                                                            type="button"
                                                            onClick={() => toggleFiliere(f.value)}
                                                            className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${
                                                                selectedFilieres.includes(f.value)
                                                                    ? 'bg-primary-500 text-white shadow-sm'
                                                                    : 'bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700'
                                                            }`}
                                                        >
                                                            {f.short}
                                                        </button>
                                                    ))}
                                                </div>
                                            </div>
                                            <div>
                                                <p className="text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5 uppercase tracking-wider">Promotions</p>
                                                <div className="flex flex-wrap gap-1.5">
                                                    {PROMOTIONS.map((p) => (
                                                        <button
                                                            key={p.value}
                                                            type="button"
                                                            onClick={() => togglePromotion(p.value)}
                                                            className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${
                                                                selectedPromotions.includes(p.value)
                                                                    ? 'bg-primary-500 text-white shadow-sm'
                                                                    : 'bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700'
                                                            }`}
                                                        >
                                                            {p.short}
                                                        </button>
                                                    ))}
                                                </div>
                                            </div>
                                            {(selectedFilieres.length > 0 || selectedPromotions.length > 0) && (
                                                <div className="bg-primary-50 dark:bg-primary-900/10 rounded-lg p-2 text-xs text-primary-700 dark:text-primary-300 font-medium">
                                                    <Target size={12} className="inline mr-1" />
                                                    {selectedFilieres.length > 0 && selectedFilieres.map(f => FILIERES.find(x => x.value === f)?.short).join(', ')}
                                                    {selectedFilieres.length > 0 && selectedPromotions.length > 0 && ' · '}
                                                    {selectedPromotions.length > 0 && selectedPromotions.map(p => PROMOTIONS.find(x => x.value === p)?.short).join(', ')}
                                                </div>
                                            )}
                                            {!targetAll && selectedFilieres.length === 0 && selectedPromotions.length === 0 && (
                                                <p className="text-xs text-amber-500 font-medium">⚠ Aucun filtre sélectionné — visible par tous</p>
                                            )}
                                        </div>
                                    )}
                                </div>

                                <div>
                                    <label className="text-sm font-bold text-slate-700 dark:text-slate-300 mb-1 block">Date limite (optionnel)</label>
                                    <input
                                        type="datetime-local"
                                        className="input"
                                        value={deadline}
                                        onChange={(e) => setDeadline(e.target.value)}
                                    />
                                </div>
                                <div className="flex justify-end gap-3 pt-2">
                                    <button type="button" onClick={() => { setShowForm(false); resetForm(); }} className="px-5 py-2 text-slate-600 font-medium hover:bg-slate-50 dark:hover:bg-slate-800 rounded-lg">
                                        Annuler
                                    </button>
                                    <button type="submit" disabled={submitting} className="btn-primary px-6 flex items-center gap-2">
                                        {submitting ? <Loader2 size={16} className="animate-spin" /> : <Send size={16} />}
                                        Lancer le Sondage
                                    </button>
                                </div>
                            </form>
                        </div>
                    </div>
                )}

                {/* Polls List */}
                {loading ? (
                    <div className="py-20 flex justify-center">
                        <Loader2 className="animate-spin text-primary-500" size={32} />
                    </div>
                ) : polls.length === 0 ? (
                    <div className="card p-16 text-center border-dashed">
                        <BarChart3 size={40} className="mx-auto mb-3 text-slate-300 dark:text-slate-600" />
                        <p className="text-slate-400 font-medium">Aucun sondage pour le moment.</p>
                    </div>
                ) : (
                    <div className="space-y-6">
                        {polls.map((poll) => {
                            const isExpired = poll.deadline && new Date(poll.deadline) < new Date();
                            const isClosed = !poll.active || isExpired;
                            const canVote = !isDelegue && !poll.userVoted && !isClosed;

                            return (
                                <div key={poll.id} className="card !p-0 overflow-hidden">
                                    <div className="p-5">
                                        {/* Poll header */}
                                        <div className="flex items-start justify-between gap-4 mb-4">
                                            <div className="flex-1">
                                                <div className="flex items-center gap-2 mb-1 flex-wrap">
                                                    {isClosed ? (
                                                        <span className="px-2.5 py-0.5 rounded-lg text-[10px] font-bold bg-slate-100 text-slate-500 dark:bg-slate-800 dark:text-slate-400">
                                                            <Lock size={10} className="inline mr-0.5" /> Clôturé
                                                        </span>
                                                    ) : (
                                                        <span className="px-2.5 py-0.5 rounded-lg text-[10px] font-bold bg-green-100 text-green-600 dark:bg-green-900/30 dark:text-green-400">
                                                            <Clock size={10} className="inline mr-0.5" /> En cours
                                                        </span>
                                                    )}
                                                    {poll.userVoted && (
                                                        <span className="px-2.5 py-0.5 rounded-lg text-[10px] font-bold bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400">
                                                            <CheckCircle2 size={10} className="inline mr-0.5" /> Voté
                                                        </span>
                                                    )}
                                                    <TargetBadge targetAll={poll.targetAll} targetLabel={poll.targetLabel} />
                                                </div>
                                                <h3 className="text-lg font-bold text-slate-800 dark:text-white">{poll.question}</h3>
                                                <div className="flex items-center gap-3 mt-1 text-xs text-slate-400">
                                                    <span>{poll.createdAt ? new Date(poll.createdAt).toLocaleDateString('fr-FR') : ''}</span>
                                                    <span>&middot;</span>
                                                    <span className="flex items-center gap-1"><Users size={12} /> {poll.totalVotes} vote{poll.totalVotes !== 1 ? 's' : ''}</span>
                                                    {poll.deadline && (
                                                        <>
                                                            <span>&middot;</span>
                                                            <span>Limite : {new Date(poll.deadline).toLocaleDateString('fr-FR')}</span>
                                                        </>
                                                    )}
                                                </div>
                                            </div>

                                            {/* Delegate actions */}
                                            {isDelegue && (
                                                <div className="flex items-center gap-1 shrink-0">
                                                    {poll.active && !isExpired && (
                                                        <button
                                                            onClick={() => handleClose(poll.id)}
                                                            className="p-2 text-slate-400 hover:text-amber-500 hover:bg-amber-50 dark:hover:bg-amber-900/20 rounded-lg transition-colors"
                                                            title="Clôturer"
                                                        >
                                                            <Lock size={16} />
                                                        </button>
                                                    )}
                                                    <button
                                                        onClick={() => handleDelete(poll.id)}
                                                        className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                                                        title="Supprimer"
                                                    >
                                                        <Trash2 size={16} />
                                                    </button>
                                                </div>
                                            )}
                                        </div>

                                        {/* Options */}
                                        <div className="space-y-2">
                                            {poll.options.map((opt) => {
                                                const isSelected = poll.userVotedOptionIndex === opt.index;
                                                const showResults = poll.userVoted || isDelegue || isClosed;

                                                return (
                                                    <div key={opt.index}>
                                                        <button
                                                            onClick={() => canVote && handleVote(poll.id, opt.index)}
                                                            disabled={!canVote}
                                                            className={`w-full text-left p-3 rounded-xl border transition-all relative overflow-hidden ${
                                                                isSelected
                                                                    ? 'border-primary-300 dark:border-primary-700 bg-primary-50 dark:bg-primary-900/20'
                                                                    : canVote
                                                                        ? 'border-slate-200 dark:border-slate-700 hover:border-primary-300 dark:hover:border-primary-700 hover:bg-slate-50 dark:hover:bg-slate-800 cursor-pointer'
                                                                        : 'border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-800/30'
                                                            }`}
                                                        >
                                                            {/* Progress bar background */}
                                                            {showResults && (
                                                                <div
                                                                    className={`absolute inset-0 transition-all ${isSelected ? 'bg-primary-100/50 dark:bg-primary-900/20' : 'bg-slate-100/50 dark:bg-slate-800/30'}`}
                                                                    style={{ width: `${opt.percentage}%` }}
                                                                />
                                                            )}
                                                            <div className="relative flex items-center justify-between">
                                                                <div className="flex items-center gap-2">
                                                                    {isSelected && <CheckCircle2 size={16} className="text-primary-600 dark:text-primary-400" />}
                                                                    <span className={`font-medium text-sm ${isSelected ? 'text-primary-700 dark:text-primary-300' : 'text-slate-700 dark:text-slate-300'}`}>
                                                                        {opt.text}
                                                                    </span>
                                                                </div>
                                                                {showResults && (
                                                                    <div className="flex items-center gap-2">
                                                                        <span className="text-xs font-bold text-slate-500">{opt.voteCount}</span>
                                                                        <span className="text-xs font-bold text-slate-400">({opt.percentage}%)</span>
                                                                    </div>
                                                                )}
                                                            </div>
                                                        </button>

                                                        {/* Delegate: show voters */}
                                                        {isDelegue && opt.voterNames && opt.voterNames.length > 0 && (
                                                            <div className="ml-3 mt-1">
                                                                <button
                                                                    onClick={() => toggleVoters(poll.id, opt.index)}
                                                                    className="text-xs text-slate-400 hover:text-slate-600 flex items-center gap-1"
                                                                >
                                                                    <Users size={12} />
                                                                    {opt.voterNames.length} votant{opt.voterNames.length > 1 ? 's' : ''}
                                                                    {expandedVoters[`${poll.id}-${opt.index}`] ? <ChevronUp size={12} /> : <ChevronDown size={12} />}
                                                                </button>
                                                                {expandedVoters[`${poll.id}-${opt.index}`] && (
                                                                    <div className="mt-1 pl-4 py-1 border-l-2 border-slate-200 dark:border-slate-700">
                                                                        {opt.voterNames.map((name, i) => (
                                                                            <p key={i} className="text-xs text-slate-500 py-0.5">{name}</p>
                                                                        ))}
                                                                    </div>
                                                                )}
                                                            </div>
                                                        )}
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>
        </DashboardLayout>
    );
};

export default PollsPage;

import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { Link } from 'react-router-dom';
import { User, Mail, Lock, Loader2, AlertCircle, ArrowRight, CheckCircle2, Eye, EyeOff, GraduationCap, BookOpen } from 'lucide-react';
import Logo from '../components/Logo';

const FILIERES = [
    { value: 'INFO', label: 'Informatique', icon: '💻' },
    { value: 'INFOTRO', label: 'Infotronique', icon: '🔌' },
    { value: 'MECA', label: 'Mécatronique', icon: '⚙️' },
    { value: 'GSIL', label: 'GSIL', icon: '🏭' }
];

const PROMOTIONS = [
    { value: 'PREMIERE_ANNEE', label: '1ère année', short: '1A' },
    { value: 'DEUXIEME_ANNEE', label: '2ème année', short: '2A' },
    { value: 'TROISIEME_ANNEE', label: '3ème année', short: '3A' }
];

const RegisterPage = () => {
    const [formData, setFormData] = useState({
        email: '',
        password: '',
        fullName: '',
        filiere: '',
        promotion: ''
    });
    const [showPassword, setShowPassword] = useState(false);
    const [loading, setLoading] = useState(false);
    const [success, setSuccess] = useState(false);
    const [registeredEmail, setRegisteredEmail] = useState('');
    const [error, setError] = useState('');
    const { register } = useAuth();

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    // Password strength
    const getPasswordStrength = (pwd) => {
        let score = 0;
        if (pwd.length >= 8) score++;
        if (/[A-Z]/.test(pwd)) score++;
        if (/[0-9]/.test(pwd)) score++;
        if (/[^A-Za-z0-9]/.test(pwd)) score++;
        return score;
    };

    const strength = getPasswordStrength(formData.password);
    const strengthLabels = ['', 'Faible', 'Moyen', 'Bon', 'Excellent'];
    const strengthColors = ['', 'bg-red-500', 'bg-orange-500', 'bg-blue-500', 'bg-green-500'];

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!formData.filiere || !formData.promotion) {
            setError('Veuillez sélectionner votre filière et votre promotion.');
            return;
        }
        setLoading(true);
        setError('');
        try {
            await register(formData);
            setRegisteredEmail(formData.email);
            setSuccess(true);
        } catch (err) {
            setError(err.response?.data?.message || 'Échec de l\'inscription. Veuillez réessayer.');
        } finally {
            setLoading(false);
        }
    };

    if (success) {
        return (
            <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex items-center justify-center p-4">
                <div className="max-w-md w-full card !p-8 text-center animate-in fade-in zoom-in duration-300">
                    <div className="flex justify-center mb-6">
                        <Logo className="scale-125" textColor="text-slate-800 dark:text-slate-100" />
                    </div>
                    <div className="w-16 h-16 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-full flex items-center justify-center mx-auto mb-4">
                        <Mail size={32} />
                    </div>
                    <h2 className="text-2xl font-bold text-slate-800 dark:text-white mb-2">Vérifiez votre email !</h2>
                    <p className="text-slate-500 dark:text-slate-400 mb-2">
                        Un email de vérification a été envoyé à :
                    </p>
                    <p className="text-primary-600 dark:text-primary-400 font-bold text-lg mb-6">
                        {registeredEmail}
                    </p>
                    <p className="text-sm text-slate-400 dark:text-slate-500 mb-6">
                        Cliquez sur le lien dans l'email pour activer votre compte.
                    </p>
                    <Link
                        to="/login"
                        className="text-primary-600 dark:text-primary-400 font-bold hover:underline underline-offset-4"
                    >
                        Aller à la connexion
                    </Link>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex items-center justify-center p-4 transition-colors duration-300">
            <div className="max-w-md w-full card !p-8 animate-in fade-in zoom-in duration-300">
                <div className="text-center mb-8">
                    <div className="flex justify-center mb-6">
                        <Logo className="scale-125" textColor="text-slate-800 dark:text-slate-100" />
                    </div>
                    <h1 className="text-3xl font-bold text-slate-800 dark:text-white tracking-tight">Créer un compte</h1>
                    <p className="text-slate-500 dark:text-slate-400 mt-2 font-medium">Rejoignez la plateforme EniGov</p>
                </div>

                {error && (
                    <div className="bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 p-4 rounded-xl text-sm mb-6 flex items-start gap-3 border border-red-100 dark:border-red-900/30">
                        <AlertCircle className="shrink-0 mt-0.5" size={18} />
                        <span>{error}</span>
                    </div>
                )}

                <form onSubmit={handleSubmit} className="space-y-4">
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1">Nom complet</label>
                        <div className="relative group">
                            <User className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary-500 transition-colors" size={18} />
                            <input
                                type="text"
                                name="fullName"
                                value={formData.fullName}
                                onChange={handleChange}
                                className="input !pl-10 !py-2.5"
                                placeholder="Votre nom complet"
                                required
                            />
                        </div>
                    </div>

                    {/* Filière Selection */}
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1 flex items-center gap-1">
                            <GraduationCap size={12} /> Filière
                        </label>
                        <div className="grid grid-cols-2 gap-2">
                            {FILIERES.map((f) => (
                                <button
                                    key={f.value}
                                    type="button"
                                    onClick={() => setFormData({ ...formData, filiere: f.value })}
                                    className={`p-2.5 rounded-xl border-2 text-sm font-semibold transition-all flex items-center gap-2 ${
                                        formData.filiere === f.value
                                            ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20 text-primary-700 dark:text-primary-300 shadow-sm shadow-primary-100 dark:shadow-none'
                                            : 'border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-400 hover:border-slate-300 dark:hover:border-slate-600 hover:bg-slate-50 dark:hover:bg-slate-800'
                                    }`}
                                >
                                    <span className="text-lg">{f.icon}</span>
                                    <span className="truncate">{f.label}</span>
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Promotion Selection */}
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1 flex items-center gap-1">
                            <BookOpen size={12} /> Promotion
                        </label>
                        <div className="grid grid-cols-3 gap-2">
                            {PROMOTIONS.map((p) => (
                                <button
                                    key={p.value}
                                    type="button"
                                    onClick={() => setFormData({ ...formData, promotion: p.value })}
                                    className={`p-2.5 rounded-xl border-2 text-sm font-bold transition-all text-center ${
                                        formData.promotion === p.value
                                            ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20 text-primary-700 dark:text-primary-300 shadow-sm shadow-primary-100 dark:shadow-none'
                                            : 'border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-400 hover:border-slate-300 dark:hover:border-slate-600 hover:bg-slate-50 dark:hover:bg-slate-800'
                                    }`}
                                >
                                    {p.short}
                                    <span className="block text-[10px] font-medium mt-0.5 opacity-70">{p.label}</span>
                                </button>
                            ))}
                        </div>
                    </div>

                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1">Email</label>
                        <div className="relative group">
                            <Mail className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary-500 transition-colors" size={18} />
                            <input
                                type="email"
                                name="email"
                                value={formData.email}
                                onChange={handleChange}
                                className="input !pl-10 !py-2.5"
                                placeholder="prenom.nom@enicar.ucar.tn"
                                required
                            />
                        </div>
                    </div>

                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1">Mot de passe</label>
                        <div className="relative group">
                            <Lock className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary-500 transition-colors" size={18} />
                            <input
                                type={showPassword ? 'text' : 'password'}
                                name="password"
                                value={formData.password}
                                onChange={handleChange}
                                className="input !pl-10 !pr-10 !py-2.5"
                                placeholder="••••••••"
                                required
                            />
                            <button
                                type="button"
                                onClick={() => setShowPassword(!showPassword)}
                                className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 transition-colors"
                            >
                                {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                            </button>
                        </div>
                        {formData.password && (
                            <div className="space-y-1.5 mt-1">
                                <div className="flex gap-1">
                                    {[1, 2, 3, 4].map((level) => (
                                        <div
                                            key={level}
                                            className={`h-1 flex-1 rounded-full transition-colors ${strength >= level ? strengthColors[strength] : 'bg-slate-200 dark:bg-slate-700'
                                                }`}
                                        />
                                    ))}
                                </div>
                                <p className={`text-[11px] font-medium ${strength <= 1 ? 'text-red-500' :
                                    strength === 2 ? 'text-orange-500' :
                                        strength === 3 ? 'text-blue-500' : 'text-green-500'
                                    }`}>
                                    {strengthLabels[strength]}
                                    {strength < 3 && ' — min. 8 caractères, 1 majuscule, 1 chiffre'}
                                </p>
                            </div>
                        )}
                    </div>

                    <button
                        type="submit"
                        disabled={loading || strength < 3 || !formData.filiere || !formData.promotion}
                        className="btn-primary w-full !py-3.5 flex items-center justify-center gap-2 mt-4 shadow-lg shadow-primary-200 dark:shadow-none disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        {loading ? (
                            <Loader2 className="animate-spin" size={20} />
                        ) : (
                            <>
                                <span>S'inscrire</span>
                                <ArrowRight size={20} />
                            </>
                        )}
                    </button>
                </form>

                <div className="mt-8 pt-6 border-t border-slate-50 dark:border-slate-800 text-center">
                    <p className="text-slate-500 dark:text-slate-400 text-sm font-medium">
                        Vous avez déjà un compte ?{' '}
                        <Link to="/login" className="text-primary-600 dark:text-primary-400 font-bold hover:underline underline-offset-4">
                            Se connecter
                        </Link>
                    </p>
                </div>
            </div>
        </div>
    );
};

export default RegisterPage;

import React, { useState, useEffect } from 'react';
import DashboardLayout from '../components/DashboardLayout';
import api from '../services/api';
import { useAuth } from '../context/AuthContext';
import {
    FileText,
    Plus,
    Download,
    Trash2,
    Send,
    Loader2,
    Paperclip,
    X,
    Calendar
} from 'lucide-react';

const RegulationsPage = () => {
    const { user } = useAuth();
    const isDelegue = user?.role === 'ROLE_DELEGUE';

    const [regulations, setRegulations] = useState([]);
    const [loading, setLoading] = useState(true);
    const [showForm, setShowForm] = useState(false);
    const [title, setTitle] = useState('');
    const [description, setDescription] = useState('');
    const [file, setFile] = useState(null);
    const [submitting, setSubmitting] = useState(false);

    useEffect(() => {
        fetchRegulations();
    }, []);

    const fetchRegulations = async () => {
        setLoading(true);
        try {
            const res = await api.get('/regulations');
            setRegulations(res.data);
        } catch {
            setRegulations([]);
        } finally {
            setLoading(false);
        }
    };

    const handleCreate = async (e) => {
        e.preventDefault();
        if (!title.trim() || !file) return;
        setSubmitting(true);
        try {
            const data = new FormData();
            data.append('title', title);
            if (description) data.append('description', description);
            data.append('file', file);

            await api.post('/regulations', data);
            setShowForm(false);
            setTitle('');
            setDescription('');
            setFile(null);
            fetchRegulations();
        } catch (err) {
            alert(err.response?.data?.message || 'Erreur lors de l\'upload');
        } finally {
            setSubmitting(false);
        }
    };

    const handleDelete = async (id) => {
        if (!window.confirm('Supprimer ce règlement ?')) return;
        try {
            await api.delete(`/regulations/${id}`);
            fetchRegulations();
        } catch (err) {
            alert(err.response?.data?.message || 'Erreur');
        }
    };

    const getFileUrl = (filePath) => {
        return `${import.meta.env.VITE_API_URL?.replace('/api', '') || 'http://localhost:8081'}/uploads/${filePath}`;
    };

    return (
        <DashboardLayout title="Règlements et documents">
            <div className="max-w-4xl mx-auto space-y-6">
                {/* Header */}
                <div className="flex items-center justify-between">
                    <div>
                        <h1 className="text-xl font-bold text-slate-800 dark:text-white">Règlements et documents</h1>
                        <p className="text-sm text-slate-500">Documents officiels et règlements intérieurs</p>
                    </div>
                    {isDelegue && (
                        <button onClick={() => setShowForm(true)} className="btn-primary flex items-center gap-2 text-sm">
                            <Plus size={16} /> Ajouter un document
                        </button>
                    )}
                </div>

                {/* Upload Modal */}
                {showForm && (
                    <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
                        <div className="bg-white dark:bg-slate-900 rounded-2xl shadow-2xl w-full max-w-lg animate-in fade-in zoom-in duration-200">
                            <div className="p-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">
                                <h3 className="text-lg font-bold text-slate-800 dark:text-white">Ajouter un document</h3>
                                <button onClick={() => setShowForm(false)} className="text-slate-400 hover:text-slate-600">
                                    <X size={20} />
                                </button>
                            </div>
                            <form onSubmit={handleCreate} className="p-5 space-y-4">
                                <div>
                                    <label className="text-sm font-bold text-slate-700 dark:text-slate-300 mb-1 block">Titre</label>
                                    <input
                                        className="input"
                                        value={title}
                                        onChange={(e) => setTitle(e.target.value)}
                                        placeholder="ex: Règlement intérieur 2026"
                                        required
                                    />
                                </div>
                                <div>
                                    <label className="text-sm font-bold text-slate-700 dark:text-slate-300 mb-1 block">Description / Notes (optionnel)</label>
                                    <textarea
                                        className="input min-h-[80px]"
                                        value={description}
                                        onChange={(e) => setDescription(e.target.value)}
                                        placeholder="ex: Aller au secteur 9 pour les attestations"
                                    />
                                </div>
                                <div>
                                    <label className="text-sm font-bold text-slate-700 dark:text-slate-300 mb-1 block">Fichier PDF</label>
                                    <label className="flex items-center justify-center gap-2 w-full p-4 border-2 border-dashed border-slate-200 dark:border-slate-700 rounded-xl cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors text-sm">
                                        <Paperclip size={16} className="text-slate-400" />
                                        <span className="text-slate-500">{file ? file.name : 'Cliquez pour sélectionner un PDF'}</span>
                                        <input type="file" onChange={(e) => setFile(e.target.files[0])} className="hidden" accept="application/pdf" required />
                                    </label>
                                </div>
                                <div className="flex justify-end gap-3 pt-2">
                                    <button type="button" onClick={() => setShowForm(false)} className="px-5 py-2 text-slate-600 font-medium hover:bg-slate-50 dark:hover:bg-slate-800 rounded-lg">
                                        Annuler
                                    </button>
                                    <button type="submit" disabled={submitting} className="btn-primary px-6 flex items-center gap-2">
                                        {submitting ? <Loader2 size={16} className="animate-spin" /> : <Send size={16} />}
                                        Publier
                                    </button>
                                </div>
                            </form>
                        </div>
                    </div>
                )}

                {/* Regulations List */}
                {loading ? (
                    <div className="py-20 flex justify-center">
                        <Loader2 className="animate-spin text-primary-500" size={32} />
                    </div>
                ) : regulations.length === 0 ? (
                    <div className="card p-16 text-center border-dashed">
                        <FileText size={40} className="mx-auto mb-3 text-slate-300 dark:text-slate-600" />
                        <p className="text-slate-400 font-medium">Aucun document pour le moment.</p>
                    </div>
                ) : (
                    <div className="space-y-3">
                        {regulations.map((reg) => (
                            <div key={reg.id} className="card !p-0 overflow-hidden">
                                <div className="p-5 flex items-center justify-between gap-4">
                                    <div className="flex items-center gap-3 flex-1 min-w-0">
                                        <div className="p-2.5 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 rounded-lg shrink-0">
                                            <FileText size={22} />
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <h3 className="font-bold text-slate-800 dark:text-white">{reg.title}</h3>
                                            {reg.description && (
                                                <p className="text-xs text-slate-500 mt-0.5 whitespace-pre-wrap">{reg.description}</p>
                                            )}
                                            <span className="text-[10px] text-slate-400 flex items-center gap-1 mt-1">
                                                <Calendar size={10} />
                                                {reg.createdAt ? new Date(reg.createdAt).toLocaleDateString('fr-FR') : ''}
                                            </span>
                                        </div>
                                    </div>

                                    <div className="flex items-center gap-2 shrink-0">
                                        {reg.filePath && (
                                            <a
                                                href={getFileUrl(reg.filePath)}
                                                target="_blank"
                                                rel="noopener noreferrer"
                                                className="flex items-center gap-1.5 px-3 py-2 bg-primary-50 dark:bg-primary-900/20 text-primary-600 dark:text-primary-400 rounded-lg text-xs font-bold hover:bg-primary-100 dark:hover:bg-primary-900/30 transition-colors"
                                            >
                                                <Download size={14} />
                                                Télécharger
                                            </a>
                                        )}
                                        {isDelegue && (
                                            <button
                                                onClick={() => handleDelete(reg.id)}
                                                className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                                                title="Supprimer"
                                            >
                                                <Trash2 size={16} />
                                            </button>
                                        )}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </DashboardLayout>
    );
};

export default RegulationsPage;

import React, { useState } from 'react';
import { useSearchParams, Link, useNavigate } from 'react-router-dom';
import { Lock, Loader2, CheckCircle2, AlertCircle, ArrowLeft, Eye, EyeOff } from 'lucide-react';
import Logo from '../components/Logo';
import api from '../services/api';

const ResetPasswordPage = () => {
    const [searchParams] = useSearchParams();
    const navigate = useNavigate();
    const token = searchParams.get('token');

    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [loading, setLoading] = useState(false);
    const [success, setSuccess] = useState(false);
    const [error, setError] = useState('');

    // Password strength checker
    const getPasswordStrength = (pwd) => {
        let score = 0;
        if (pwd.length >= 8) score++;
        if (/[A-Z]/.test(pwd)) score++;
        if (/[0-9]/.test(pwd)) score++;
        if (/[^A-Za-z0-9]/.test(pwd)) score++;
        return score;
    };

    const strength = getPasswordStrength(password);
    const strengthLabels = ['', 'Faible', 'Moyen', 'Bon', 'Excellent'];
    const strengthColors = ['', 'bg-red-500', 'bg-orange-500', 'bg-blue-500', 'bg-green-500'];

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');

        if (password !== confirmPassword) {
            setError('Les mots de passe ne correspondent pas.');
            return;
        }

        if (strength < 3) {
            setError('Le mot de passe doit contenir au moins 8 caractères, une majuscule et un chiffre.');
            return;
        }

        setLoading(true);
        try {
            await api.post('/auth/reset-password', { token, password });
            setSuccess(true);
            setTimeout(() => navigate('/login'), 3000);
        } catch (err) {
            setError(err.response?.data?.message || 'Une erreur est survenue.');
        } finally {
            setLoading(false);
        }
    };

    if (!token) {
        return (
            <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex items-center justify-center p-4">
                <div className="max-w-md w-full card !p-8 text-center">
                    <h2 className="text-2xl font-bold text-slate-800 dark:text-white mb-4">Lien invalide</h2>
                    <p className="text-slate-500 dark:text-slate-400 mb-6">Ce lien de réinitialisation est invalide ou a expiré.</p>
                    <Link to="/forgot-password" className="text-primary-600 dark:text-primary-400 font-bold hover:underline">
                        Demander un nouveau lien
                    </Link>
                </div>
            </div>
        );
    }

    if (success) {
        return (
            <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex items-center justify-center p-4">
                <div className="max-w-md w-full card !p-8 text-center animate-in fade-in zoom-in duration-300">
                    <div className="w-16 h-16 bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400 rounded-full flex items-center justify-center mx-auto mb-4">
                        <CheckCircle2 size={32} />
                    </div>
                    <h2 className="text-2xl font-bold text-slate-800 dark:text-white mb-2">Mot de passe réinitialisé !</h2>
                    <p className="text-slate-500 dark:text-slate-400">Redirection vers la connexion...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex items-center justify-center p-4">
            <div className="max-w-md w-full card !p-8 animate-in fade-in zoom-in duration-300">
                <div className="text-center mb-8">
                    <div className="flex justify-center mb-6">
                        <Logo className="scale-125" textColor="text-slate-800 dark:text-slate-100" />
                    </div>
                    <h1 className="text-2xl font-bold text-slate-800 dark:text-white tracking-tight">Nouveau mot de passe</h1>
                    <p className="text-slate-500 dark:text-slate-400 mt-2 font-medium">
                        Choisissez un nouveau mot de passe sécurisé.
                    </p>
                </div>

                {error && (
                    <div className="bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 p-4 rounded-xl text-sm mb-6 flex items-start gap-3 border border-red-100 dark:border-red-900/30">
                        <AlertCircle className="shrink-0 mt-0.5" size={18} />
                        <span>{error}</span>
                    </div>
                )}

                <form onSubmit={handleSubmit} className="space-y-5">
                    <div className="space-y-2">
                        <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1">Nouveau mot de passe</label>
                        <div className="relative group">
                            <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary-500 transition-colors" size={20} />
                            <input
                                type={showPassword ? 'text' : 'password'}
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="input !pl-12 !pr-12 !py-3.5"
                                placeholder="••••••••"
                                required
                            />
                            <button
                                type="button"
                                onClick={() => setShowPassword(!showPassword)}
                                className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 transition-colors"
                            >
                                {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                            </button>
                        </div>
                        {password && (
                            <div className="space-y-1.5 mt-2">
                                <div className="flex gap-1">
                                    {[1, 2, 3, 4].map((level) => (
                                        <div
                                            key={level}
                                            className={`h-1.5 flex-1 rounded-full transition-colors ${strength >= level ? strengthColors[strength] : 'bg-slate-200 dark:bg-slate-700'
                                                }`}
                                        />
                                    ))}
                                </div>
                                <p className={`text-xs font-medium ${strength <= 1 ? 'text-red-500' :
                                        strength === 2 ? 'text-orange-500' :
                                            strength === 3 ? 'text-blue-500' : 'text-green-500'
                                    }`}>
                                    {strengthLabels[strength]}
                                    {strength < 3 && ' — min. 8 caractères, 1 majuscule, 1 chiffre'}
                                </p>
                            </div>
                        )}
                    </div>

                    <div className="space-y-2">
                        <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ml-1">Confirmer</label>
                        <div className="relative group">
                            <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary-500 transition-colors" size={20} />
                            <input
                                type="password"
                                value={confirmPassword}
                                onChange={(e) => setConfirmPassword(e.target.value)}
                                className="input !pl-12 !py-3.5"
                                placeholder="••••••••"
                                required
                            />
                        </div>
                        {confirmPassword && password !== confirmPassword && (
                            <p className="text-xs text-red-500 font-medium ml-1">Les mots de passe ne correspondent pas.</p>
                        )}
                    </div>

                    <button
                        type="submit"
                        disabled={loading || strength < 3 || password !== confirmPassword}
                        className="btn-primary w-full !py-4 flex items-center justify-center gap-3 shadow-lg shadow-primary-200 dark:shadow-none disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        {loading ? (
                            <Loader2 className="animate-spin" size={22} />
                        ) : (
                            <span className="text-lg">Réinitialiser</span>
                        )}
                    </button>
                </form>

                <div className="mt-8 pt-6 border-t border-slate-50 dark:border-slate-800 text-center">
                    <Link
                        to="/login"
                        className="text-primary-600 dark:text-primary-400 font-bold hover:underline underline-offset-4 inline-flex items-center gap-2"
                    >
                        <ArrowLeft size={16} /> Retour à la connexion
                    </Link>
                </div>
            </div>
        </div>
    );
};

export default ResetPasswordPage;

import React, { useState } from 'react';
import DashboardLayout from '../components/DashboardLayout';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import { useTheme } from '../context/ThemeContext';
import {
    User,
    Lock,
    Moon,
    Sun,
    Shield,
    Palette,
    Camera,
    Save,
    CheckCircle2,
    Loader2,
    AlertCircle,
    Eye,
    EyeOff,
    Laptop,
    Cpu,
    Settings as SettingsIcon,
    Factory
} from 'lucide-react';

const SettingsPage = () => {
    const { user, updateUser } = useAuth();
    const { theme, toggleTheme } = useTheme();
    const darkMode = theme === 'dark';
    const [activeTab, setActiveTab] = useState('profile');
    const [saved, setSaved] = useState(false);
    const [showLightbox, setShowLightbox] = useState(false);

    // Profile form
    const [fullName, setFullName] = useState(user?.fullName || '');
    const [profileLoading, setProfileLoading] = useState(false);
    const [profileError, setProfileError] = useState('');

    // Password form
    const [currentPassword, setCurrentPassword] = useState('');
    const [newPassword, setNewPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [showNewPassword, setShowNewPassword] = useState(false);
    const [passwordLoading, setPasswordLoading] = useState(false);
    const [passwordError, setPasswordError] = useState('');
    const [passwordSuccess, setPasswordSuccess] = useState(false);

    // Password strength
    const getPasswordStrength = (pwd) => {
        let score = 0;
        if (pwd.length >= 8) score++;
        if (/[A-Z]/.test(pwd)) score++;
        if (/[0-9]/.test(pwd)) score++;
        if (/[^A-Za-z0-9]/.test(pwd)) score++;
        return score;
    };

    const strength = getPasswordStrength(newPassword);
    const strengthLabels = ['', 'Faible', 'Moyen', 'Bon', 'Excellent'];
    const strengthColors = ['', 'bg-red-500', 'bg-orange-500', 'bg-blue-500', 'bg-green-500'];

    const handleProfileSave = async (e) => {
        e.preventDefault();
        setProfileLoading(true);
        setProfileError('');
        try {
            await api.updateProfile({ fullName });
            updateUser({ fullName });
            setSaved(true);
            setTimeout(() => setSaved(false), 3000);
        } catch (error) {
            setProfileError(error.response?.data?.message || "Erreur lors de la mise à jour.");
        } finally {
            setProfileLoading(false);
        }
    };

    const handlePasswordChange = async (e) => {
        e.preventDefault();
        setPasswordError('');
        setPasswordSuccess(false);

        if (newPassword !== confirmPassword) {
            setPasswordError('Les mots de passe ne correspondent pas.');
            return;
        }

        if (strength < 3) {
            setPasswordError('Le mot de passe doit contenir au moins 8 caractères, une majuscule et un chiffre.');
            return;
        }

        setPasswordLoading(true);
        try {
            await api.changePassword({ currentPassword, newPassword });
            setPasswordSuccess(true);
            setCurrentPassword('');
            setNewPassword('');
            setConfirmPassword('');
            setTimeout(() => setPasswordSuccess(false), 5000);
        } catch (error) {
            setPasswordError(error.response?.data?.message || "Erreur lors du changement de mot de passe.");
        } finally {
            setPasswordLoading(false);
        }
    };

    const fileInputRef = React.useRef(null);

    const handleFileChange = async (e) => {
        const file = e.target.files[0];
        if (!file) return;

        // Client-side validation
        const allowedTypes = ['image/jpeg', 'image/png', 'image/webp'];
        if (!allowedTypes.includes(file.type)) {
            alert('Format non supporté. Utilisez JPG, PNG ou WebP.');
            return;
        }
        if (file.size > 5 * 1024 * 1024) {
            alert('Le fichier est trop volumineux. Maximum 5 Mo.');
            return;
        }

        const data = new FormData();
        data.append('file', file);

        try {
            const response = await api.uploadPhoto(data);
            const photoUrl = response.data.profilePhoto;
            updateUser({ profilePhoto: photoUrl });
        } catch (error) {
            const msg = error.response?.data?.message || error.message;
            alert(`Erreur upload: ${msg}`);
        }
    };

    const tabs = [
        { id: 'profile', label: 'Profil', icon: User },
        { id: 'appearance', label: 'Apparence', icon: Palette },
        { id: 'security', label: 'Sécurité', icon: Shield }
    ];

    return (
        <DashboardLayout title="Paramètres">
            <div className="max-w-5xl mx-auto flex flex-col md:flex-row gap-8">
                {/* Sidebar Navigation */}
                <div className="w-full md:w-64 space-y-1">
                    {tabs.map((tab) => (
                        <button
                            key={tab.id}
                            onClick={() => setActiveTab(tab.id)}
                            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${activeTab === tab.id
                                ? 'bg-primary-600 text-white shadow-lg shadow-primary-200 dark:shadow-none translate-x-1'
                                : 'text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'
                                }`}
                        >
                            <tab.icon size={20} />
                            <span>{tab.label}</span>
                        </button>
                    ))}
                </div>

                {/* Content Area */}
                <div className="flex-1">
                    <div className="card shadow-xl border-none">
                        {activeTab === 'profile' && (
                            <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                                <div className="flex items-center gap-6 mb-8">
                                    <div className="relative group">
                                        <div
                                            className="w-24 h-24 bg-primary-100 dark:bg-primary-900/30 rounded-2xl flex items-center justify-center text-primary-600 dark:text-primary-400 text-3xl font-bold border-4 border-white dark:border-slate-800 shadow-md overflow-hidden cursor-pointer"
                                            onClick={() => user?.profilePhoto && setShowLightbox(true)}
                                        >
                                            {user?.profilePhoto ? (
                                                <img
                                                    src={user.profilePhoto.startsWith('http') ? user.profilePhoto : `${import.meta.env.VITE_API_URL?.replace('/api', '') || 'http://localhost:8081'}/uploads/${user.profilePhoto}`}
                                                    alt="Profile"
                                                    className="w-full h-full object-cover transition-transform hover:scale-110"
                                                />
                                            ) : (
                                                user?.fullName?.charAt(0) || 'U'
                                            )}
                                        </div>
                                        <button
                                            type="button"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                fileInputRef.current.click();
                                            }}
                                            className="absolute -bottom-2 -right-2 p-2 bg-white dark:bg-slate-700 shadow-lg rounded-xl text-slate-600 dark:text-slate-300 hover:text-primary-600 transition-colors border border-slate-100 dark:border-slate-600 z-10"
                                        >
                                            <Camera size={16} />
                                        </button>
                                        <input
                                            type="file"
                                            ref={fileInputRef}
                                            onChange={handleFileChange}
                                            className="hidden"
                                            accept="image/jpeg,image/png,image/webp"
                                        />
                                    </div>
                                    <div>
                                        <h3 className="text-xl font-bold text-slate-800 dark:text-white">{user?.fullName}</h3>
                                        <p className="text-slate-500 font-medium">{user?.role === 'ROLE_DELEGUE' ? 'Délégué' : 'Étudiant'}</p>
                                        <p className="text-sm text-slate-400 mt-0.5">{user?.email}</p>
                                        {user?.filiere && (
                                            <div className="flex items-center gap-2 mt-2 flex-wrap">
                                                <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-bold bg-primary-50 text-primary-600 dark:bg-primary-900/20 dark:text-primary-400">
                                                    {user.filiere === 'INFO' ? <><Laptop size={12} /> Informatique</> :
                                                     user.filiere === 'INFOTRO' ? <><Cpu size={12} /> Infotronique</> :
                                                     user.filiere === 'MECA' ? <><SettingsIcon size={12} /> Mécatronique</> :
                                                     user.filiere === 'GSIL' ? <><Factory size={12} /> GSIL</> : user.filiere}
                                                </span>
                                                {user?.promotion && (
                                                    <span className="inline-flex items-center px-2.5 py-1 rounded-lg text-xs font-bold bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400">
                                                        {user.promotion === 'PREMIERE_ANNEE' ? '1ère année' :
                                                         user.promotion === 'DEUXIEME_ANNEE' ? '2ème année' :
                                                         user.promotion === 'TROISIEME_ANNEE' ? '3ème année' : user.promotion}
                                                    </span>
                                                )}
                                            </div>
                                        )}
                                    </div>
                                </div>

                                {/* Lightbox Modal */}
                                {showLightbox && user?.profilePhoto && (
                                    <div
                                        className="fixed inset-0 z-50 bg-black/90 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in duration-200"
                                        onClick={() => setShowLightbox(false)}
                                    >
                                        <div className="relative max-w-4xl max-h-[90vh]">
                                            <img
                                                src={user.profilePhoto.startsWith('http') ? user.profilePhoto : `${import.meta.env.VITE_API_URL?.replace('/api', '') || 'http://localhost:8081'}/uploads/${user.profilePhoto}`}
                                                alt="Profile Full Size"
                                                className="max-w-full max-h-[90vh] rounded-lg shadow-2xl"
                                                onClick={(e) => e.stopPropagation()}
                                            />
                                            <button
                                                className="absolute -top-12 right-0 text-white hover:text-primary-400 transition-colors"
                                                onClick={() => setShowLightbox(false)}
                                            >
                                                <span className="text-sm font-bold uppercase tracking-widest">Fermer</span>
                                            </button>
                                        </div>
                                    </div>
                                )}

                                {profileError && (
                                    <div className="bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 p-4 rounded-xl text-sm mb-6 flex items-start gap-3 border border-red-100 dark:border-red-900/30">
                                        <AlertCircle className="shrink-0 mt-0.5" size={18} />
                                        <span>{profileError}</span>
                                    </div>
                                )}

                                <form onSubmit={handleProfileSave} className="space-y-6">
                                    <div className="space-y-2">
                                        <label className="text-sm font-bold text-slate-700 dark:text-slate-300">Nom Complet</label>
                                        <div className="relative group">
                                            <User className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary-500 transition-colors" size={18} />
                                            <input
                                                type="text"
                                                value={fullName}
                                                onChange={(e) => setFullName(e.target.value)}
                                                className="input !pl-10"
                                            />
                                        </div>
                                    </div>
                                    <div className="pt-4 border-t border-slate-50 dark:border-slate-800 flex justify-end">
                                        <button type="submit" disabled={profileLoading} className="btn-primary flex items-center gap-2 px-8">
                                            {profileLoading ? <Loader2 className="animate-spin" size={18} /> : <Save size={18} />}
                                            <span>Enregistrer</span>
                                        </button>
                                    </div>
                                </form>
                            </div>
                        )}

                        {activeTab === 'appearance' && (
                            <div className="animate-in fade-in slide-in-from-bottom-2 duration-300 space-y-8">
                                <div>
                                    <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-4">Mode d'affichage</h3>
                                    <div className="grid grid-cols-2 gap-4">
                                        <button
                                            onClick={() => darkMode && toggleTheme()}
                                            className={`p-4 rounded-2xl border-2 transition-all flex flex-col items-center gap-3 ${!darkMode ? 'border-primary-500 bg-primary-50/50 dark:bg-primary-900/10' : 'border-slate-100 dark:border-slate-800 hover:border-slate-200'}`}
                                        >
                                            <div className="w-12 h-12 rounded-xl bg-white shadow-sm flex items-center justify-center text-orange-500">
                                                <Sun size={24} />
                                            </div>
                                            <span className="font-bold text-slate-700 dark:text-slate-300">Mode Clair</span>
                                        </button>
                                        <button
                                            onClick={() => !darkMode && toggleTheme()}
                                            className={`p-4 rounded-2xl border-2 transition-all flex flex-col items-center gap-3 ${darkMode ? 'border-primary-500 bg-primary-50/50 dark:bg-primary-900/10' : 'border-slate-100 dark:border-slate-800 hover:border-slate-200'}`}
                                        >
                                            <div className="w-12 h-12 rounded-xl bg-slate-800 shadow-sm flex items-center justify-center text-blue-400">
                                                <Moon size={24} />
                                            </div>
                                            <span className="font-bold text-slate-700 dark:text-slate-300">Mode Sombre</span>
                                        </button>
                                    </div>
                                </div>
                            </div>
                        )}

                        {activeTab === 'security' && (
                            <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                                <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-6">Changer le mot de passe</h3>

                                {passwordSuccess && (
                                    <div className="bg-green-50 dark:bg-green-900/20 text-green-600 dark:text-green-400 p-4 rounded-xl text-sm mb-6 flex items-start gap-3 border border-green-100 dark:border-green-900/30">
                                        <CheckCircle2 className="shrink-0 mt-0.5" size={18} />
                                        <span>Mot de passe modifié avec succès !</span>
                                    </div>
                                )}

                                {passwordError && (
                                    <div className="bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 p-4 rounded-xl text-sm mb-6 flex items-start gap-3 border border-red-100 dark:border-red-900/30">
                                        <AlertCircle className="shrink-0 mt-0.5" size={18} />
                                        <span>{passwordError}</span>
                                    </div>
                                )}

                                <form onSubmit={handlePasswordChange} className="space-y-4 max-w-md">
                                    <div className="space-y-2">
                                        <label className="text-sm font-bold text-slate-700 dark:text-slate-300">Mot de passe actuel</label>
                                        <div className="relative group">
                                            <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary-500 transition-colors" size={18} />
                                            <input
                                                type="password"
                                                value={currentPassword}
                                                onChange={(e) => setCurrentPassword(e.target.value)}
                                                className="input !pl-10"
                                                placeholder="••••••••"
                                                required
                                            />
                                        </div>
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-sm font-bold text-slate-700 dark:text-slate-300">Nouveau mot de passe</label>
                                        <div className="relative group">
                                            <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary-500 transition-colors" size={18} />
                                            <input
                                                type={showNewPassword ? 'text' : 'password'}
                                                value={newPassword}
                                                onChange={(e) => setNewPassword(e.target.value)}
                                                className="input !pl-10 !pr-10"
                                                placeholder="••••••••"
                                                required
                                            />
                                            <button
                                                type="button"
                                                onClick={() => setShowNewPassword(!showNewPassword)}
                                                className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 transition-colors"
                                            >
                                                {showNewPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                                            </button>
                                        </div>
                                        {newPassword && (
                                            <div className="space-y-1.5 mt-1">
                                                <div className="flex gap-1">
                                                    {[1, 2, 3, 4].map((level) => (
                                                        <div
                                                            key={level}
                                                            className={`h-1.5 flex-1 rounded-full transition-colors ${strength >= level ? strengthColors[strength] : 'bg-slate-200 dark:bg-slate-700'
                                                                }`}
                                                        />
                                                    ))}
                                                </div>
                                                <p className={`text-xs font-medium ${strength <= 1 ? 'text-red-500' :
                                                    strength === 2 ? 'text-orange-500' :
                                                        strength === 3 ? 'text-blue-500' : 'text-green-500'
                                                    }`}>
                                                    {strengthLabels[strength]}
                                                    {strength < 3 && ' — min. 8 caractères, 1 majuscule, 1 chiffre'}
                                                </p>
                                            </div>
                                        )}
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-sm font-bold text-slate-700 dark:text-slate-300">Confirmer le nouveau mot de passe</label>
                                        <div className="relative group">
                                            <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary-500 transition-colors" size={18} />
                                            <input
                                                type="password"
                                                value={confirmPassword}
                                                onChange={(e) => setConfirmPassword(e.target.value)}
                                                className="input !pl-10"
                                                placeholder="••••••••"
                                                required
                                            />
                                        </div>
                                        {confirmPassword && newPassword !== confirmPassword && (
                                            <p className="text-xs text-red-500 font-medium ml-1">Les mots de passe ne correspondent pas.</p>
                                        )}
                                    </div>
                                    <div className="pt-4 flex justify-end">
                                        <button
                                            type="submit"
                                            disabled={passwordLoading || strength < 3 || newPassword !== confirmPassword}
                                            className="btn-primary px-8 flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                                        >
                                            {passwordLoading ? <Loader2 className="animate-spin" size={18} /> : <Shield size={18} />}
                                            <span>Mettre à jour</span>
                                        </button>
                                    </div>
                                </form>
                            </div>
                        )}

                        {saved && (
                            <div className="fixed bottom-8 right-8 animate-in slide-in-from-right duration-300">
                                <div className="bg-green-500 text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3">
                                    <CheckCircle2 size={24} />
                                    <span className="font-bold">Paramètres enregistrés avec succès !</span>
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </DashboardLayout>
    );
};

